// Copies the panel's browser libraries from node_modules into public/vendor (and the fonts into public/fonts), so the
// panel runs without a build step. Bare imports ("preact") become relative ones ("./preact.js"): the CSP forbids the
// inline import map that would otherwise resolve them. Run `npm run vendor` after updating one of these packages.
import { copyFileSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const root = new URL('../', import.meta.url);
const nm = (p) => new URL(`node_modules/${p}`, root);
const out = (p) => new URL(`public/${p}`, root);
const version = (pkg) => JSON.parse(readFileSync(nm(`${pkg}/package.json`), 'utf8')).version;

// Every language file of highlight.js registers itself under its own name; these cover what agents usually write.
const LANGUAGES = ['bash', 'c', 'cpp', 'csharp', 'css', 'diff', 'dockerfile', 'go', 'ini', 'java', 'javascript', 'json',
  'kotlin', 'makefile', 'markdown', 'php', 'python', 'ruby', 'rust', 'scss', 'shell', 'sql', 'swift', 'typescript', 'xml', 'yaml'];

const REWRITE = { preact: './preact.js', 'preact/hooks': './preact-hooks.js', '@preact/signals-core': './signals-core.js' };

function vendor(from, to, { wrapUmd = false } = {}) {
  let src = readFileSync(nm(from), 'utf8').replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, '\n');
  src = src.replace(/from\s*"([^"]+)"/g, (m, spec) => (REWRITE[spec] ? `from"${REWRITE[spec]}"` : m));
  // A UMD bundle sees `module` and `exports` and hands its export to them.
  if (wrapUmd) src = `const module = { exports: {} }; const exports = module.exports;\n${src}\nexport default module.exports.default || module.exports;\n`;
  writeFileSync(out(`vendor/${to}`), src);
}

rmSync(out('vendor'), { recursive: true, force: true });
mkdirSync(out('vendor'), { recursive: true });
mkdirSync(out('fonts'), { recursive: true });

vendor('preact/dist/preact.mjs', 'preact.js');
vendor('preact/hooks/dist/hooks.mjs', 'preact-hooks.js');
vendor('@preact/signals-core/dist/signals-core.mjs', 'signals-core.js');
vendor('@preact/signals/dist/signals.mjs', 'signals.js');
vendor('htm/dist/htm.mjs', 'htm.js');
vendor('@highlightjs/cdn-assets/es/core.min.js', 'hljs.js');
for (const lang of LANGUAGES) vendor(`@highlightjs/cdn-assets/es/languages/${lang}.min.js`, `hljs-${lang}.js`);
vendor('cronstrue/dist/cronstrue.min.js', 'cronstrue.js', { wrapUmd: true });

// The code editor's CodeMirror and xterm.js are many small packages: bundled (not copied) into vendor/code, with a
// chunk per language so a tab only loads the languages of the files it opens.
await build({
  entryPoints: { editor: fileURLToPath(new URL('scripts/code-editor.entry.mjs', root)) },
  outdir: fileURLToPath(out('vendor/code')),
  bundle: true, format: 'esm', splitting: true, minify: true, target: 'es2022', chunkNames: 'chunk-[hash]', legalComments: 'none',
});
copyFileSync(nm('@xterm/xterm/css/xterm.css'), out('vendor/code/xterm.css'));

for (const [from, to] of [['geist/dist/fonts/geist-sans/Geist-Variable.woff2', 'Geist-Variable.woff2'],
  ['geist/dist/fonts/geist-mono/GeistMono-Variable.woff2', 'GeistMono-Variable.woff2'], ['geist/LICENSE.txt', 'LICENSE.txt']]) {
  copyFileSync(nm(from), out(`fonts/${to}`));
}

const pkgs = ['preact', 'htm', '@preact/signals', '@preact/signals-core', '@highlightjs/cdn-assets', 'cronstrue', 'geist',
  'codemirror', '@codemirror/language-data', '@xterm/xterm', '@xterm/addon-fit'];
writeFileSync(out('vendor/README.md'), `# Vendored browser libraries

Generated by \`npm run vendor\` (scripts/vendor.mjs); do not edit by hand.

${pkgs.map((p) => `- ${p} ${version(p)}`).join('\n')}

Licenses: preact, htm, @preact/signals (MIT); highlight.js (BSD-3-Clause); cronstrue (MIT); Geist fonts (OFL-1.1,
public/fonts/LICENSE.txt); CodeMirror, xterm.js (MIT). Highlight.js languages: ${LANGUAGES.join(', ')}.
code/: CodeMirror and xterm.js bundled by esbuild from scripts/code-editor.entry.mjs.
`);
console.log(`vendored ${readdirSync(out('vendor')).length + readdirSync(out('vendor/code')).length - 1} files`);
